INSERT INTO `banner` VALUES (1,'0.05513883958373489@-@Banner1-kran.jpg','A',0,'aboutus','Kran Consulting Pvt. Ltd. is an innovative IT consulting and software development company with 3 decades of industry presence with a primary focus on Public Administration. We have established ourselves as an organization delivering mission critical projects to Government Clients across the country.',NULL),(2,'0.35337500622354734@-@about-us-banner.jpg','D',0,'','Value added solutions and services for effective transformation of the Government Sector',NULL),(3,'0.1345909386820292@-@banner-PFMS2.jpg','D',0,'pfms360','PFMS 360 – a novel concept redefining the conventional methods of Public Finance Management ',NULL),(4,'0.5532937813159888@-@Banner2-kran.jpg','A',0,'','<div class=\"d-flex justify-content-center align-items-center text-center\" style=\"text-align: left;\">As part of achieving excellence in areas of our operation, we have set up 3 exclusive \"Centres of Excellence\"</div><ol class=\"list-unstyled m-auto pt-4 d-flex justify-content-center\">    <li style=\"text-align: center;\" class=\"\">Public Finance | Licensing & Compliance | General Administration</li></ol>',''),(5,'0.8566261908221026@-@banner-PFMS2.jpg','D',0,'pfms360','PFMS 360 – a novel concept redefining the conventional methods of Public Finance Management ',NULL),(6,'Banner3-kran.jpg','A',0,'','Value added solutions and services for effective transformation of the Government Sector',NULL),(7,'Banner4-kran.jpg','A',0,'pfms360','PFMS 360 – a novel concept redefining the conventional methods of Public Finance Management ',NULL),(8,'Screenshot 2024-06-29 at 18-40-02 RiSE Login.png','D',0,'','',NULL),(9,'0.3777441691438378@-@consultancy-banner.jpg','A',0,'getService?val=consultancy','Catalyzing Government Evolution with Tailored IT Consulting for Innovation, Efficiency, Transformation','IT Consulting'),(10,'0.8078889922700071@-@Software-development-banner.jpg','A',0,'getService?val=software-development','Delivering high quality software solutions by addressing the pain points and streamlining the customer operations','Software Design & Development'),(11,'0.011630329222295233@-@mobile-Banner.jpg','A',0,'getService?val=mobile-app-development','Enriching your digital journey with cross platform Mobile Apps comprising of innovative features and designs','Mobile App Development'),(12,'0.8105815790364375@-@Product-implemetation-banner.jpg','A',0,'getService?val=project-product-implementation','Empowering Public Sector with Tailored Software Solutions for Simplified Processes, Enhanced Efficiency, and Innovation','Project Implementation'),(13,'0.765724860600802@-@Maintenance & Support banner.jpg','A',0,'getService?val=maintenance-support','Elevate your IT operations with comprehensive Support, Maintenance, and Training Solutions Tailored by KRAN','O & M Support');
