INSERT INTO `blog` VALUES (1,'ECONOMY','More than 6 lakh calls registered in just 24 hours. An effective tool for the government to help the people of their own state and to reach out to as many stranded migrants as possible at the earliest.','0.5167812978121258@-@case3.jpg',NULL,'2020-05-07','Dr. Vidya Ramji','D','<p style=\"text-align: left;\"><br></p><p style=\"\"><b>Description :</b></p>\r\n											<font class=\"ed\"><p>The ideal \r\ncandidate will evaluate and assess systems to ensure they are operating \r\neffectively. Based on assessments, this individual will harness \r\ncollected knowledge and make adjustments to existing systems.</p></font>\r\n										\r\n										\r\n											\r\n											<b> Skills/Requirements :</b>\r\n											<font class=\"ed\"><ul><li>Strong understanding and knowledge of Linux OS and Software.</li><li>Knowledge in windows system administration will be an added advantage for the position.</li><li>Good knowledge in the installation, upgrade, and troubleshooting of OS, Software, and Hardware.</li><li>Good knowledge of installation and configuration of networking devices and hardware. Routers, Switches, Load balancers, etc.</li><li>Knowledge of LAN, Wireless, WAN, Routing, and Networking.</li><li>Exposure in Windows and Linux (Ubuntu, CentOS) Server Administration.</li><li>Good knowledge of networking protocols.</li><li>Basic knowledge in any of the cloud environments (AWS/Azure/Google Cloud).</li><li>Knowledge in Hosting control panel (cpanel)</li><li>Excellent knowledge of Security systems (Firewall, Ipsec)</li><li>Scripting - Bash/Shell.</li><li>Certifications: MCSE, RHCE, RHCT, CCNA, CCNP are added advantage.</li><li>Maintain system efficiency.</li><li>Ensure system design allows all components to work together properly.</li><li>Make recommendations for upgrades.</li><li>Evaluate and modify system performance.</li><li>Good communication and coordination skills.</li><li>Should be a team player with good attitude.</li><li>Troubleshooting and multitasking skills</li></ul></font><p>qsafafaffaafaffasfafasasfaffsaafsasfasfasfasfasfsafasffsaafsfsasafas wasfasfaf awfafas qwfqfw</p>'),(2,'TECH','A website for all government employees of the state to share stories about the people they have helped during this Covid19 crisis. 776 stories and more than 250 contributions made so far.','0.8429289544257318@-@case2(1).jpg',NULL,'2023-06-19','Mr. S Karunakaran','D','<p style=\"text-align: left;\"><b></b></p><p style=\"\"><b>Description :</b></p>\r\n											<font class=\"ed\"><p>The ideal \r\ncandidate will evaluate and assess systems to ensure they are operating \r\neffectively. Based on assessments, this individual will harness \r\ncollected knowledge and make adjustments to existing systems.</p></font>\r\n										\r\n										\r\n											\r\n											<b> Skills/Requirements :</b>\r\n											<font class=\"ed\"><ul><li>Strong understanding and knowledge of Linux OS and Software.</li><li>Knowledge in windows system administration will be an added advantage for the position.</li><li>Good knowledge in the installation, upgrade, and troubleshooting of OS, Software, and Hardware.</li><li>Good knowledge of installation and configuration of networking devices and hardware. Routers, Switches, Load balancers, etc.</li><li>Knowledge of LAN, Wireless, WAN, Routing, and Networking.</li><li>Exposure in Windows and Linux (Ubuntu, CentOS) Server Administration.</li><li>Good knowledge of networking protocols.</li><li>Basic knowledge in any of the cloud environments (AWS/Azure/Google Cloud).</li><li>Knowledge in Hosting control panel (cpanel)</li><li>Excellent knowledge of Security systems (Firewall, Ipsec)</li><li>Scripting - Bash/Shell.</li><li>Certifications: MCSE, RHCE, RHCT, CCNA, CCNP are added advantage.</li><li>Maintain system efficiency.</li><li>Ensure system design allows all components to work together properly.</li><li>Make recommendations for upgrades.</li><li>Evaluate and modify system performance.</li><li>Good communication and coordination skills.</li><li>Should be a team player with good attitude.</li><li>Troubleshooting and multitasking skills</li></ul></font><p></p>');
