INSERT INTO `careers` VALUES (1,'Y','','2025-10-15','N','Front-end Developer','','2 Years','Male','<p>The Front-End Developer is responsible for building the client-side of our web applications, creating engaging, responsive, and high-performance user interfaces. You will translate UI/UX design wireframes into actual code, ensuring the technical feasibility of designs and providing a seamless user experience across all devices and browsers.</p>\r\n','Full-Time','2025-10-15','Trivandrum','2','2025-10-15','<p><strong>Skills/Requirements :</strong></p>\r\n\r\n<ul>\r\n	<li style=\"text-align:left\">Strong proficiency in core front-end technologies including HTML5, CSS3, and modern JavaScript (ES6+).</li>\r\n	<li style=\"text-align:left\">Extensive hands-on experience with at least one modern front-end framework such as React, Angular, or Vue.js.</li>\r\n	<li style=\"text-align:left\">Practical experience with state management libraries like Redux, Vuex, or NgRx.</li>\r\n	<li style=\"text-align:left\">Proficiency in CSS preprocessors like Sass or Less and experience with CSS-in-JS libraries such as Styled Components.</li>\r\n	<li style=\"text-align:left\">Experience using front-end build tools and package managers like Webpack, Vite, npm, or Yarn.</li>\r\n	<li style=\"text-align:left\">Proficient in using Git for version control.</li>\r\n	<li style=\"text-align:left\">Expertise in creating responsive layouts using Flexbox, CSS Grid, and mobile-first principles.</li>\r\n	<li style=\"text-align:left\">A strong understanding of web performance optimization techniques including lazy loading, code splitting, and image optimization.</li>\r\n	<li style=\"text-align:left\">Experience with front-end testing frameworks such as Jest, React Testing Library, or Cypress.</li>\r\n	<li style=\"text-align:left\">Experience working in an Agile/Scrum development environment.</li>\r\n</ul>\r\n\r\n<div style=\"text-align:left\"><strong>Qualification:</strong>\r\n\r\n<ul>\r\n	<li>B.E./ B. Tech or MCA</li>\r\n	<li>Overall 5 or more years of experience in front-end development.</li>\r\n	<li>A strong portfolio of projects demonstrating skills in front-end technologies and frameworks.</li>\r\n	<li>Fluency in English and Hindi (Speaking, reading &amp; writing).</li>\r\n	<li>Fluency in Assamese preferred</li>\r\n</ul>\r\n</div>\r\n','<p><strong>Responsibilities:</strong></p>\r\n\r\n<ul>\r\n	<li>Develop new user-facing features using modern front-end frameworks and libraries.</li>\r\n	<li>Build reusable components and front-end libraries for future use.</li>\r\n	<li>Translate UI/UX design mockups and wireframes into high-quality, responsive code.</li>\r\n	<li>Leverage 5+ years of experience to implement responsive, mobile-first user interfaces for web applications using frameworks like React, Angular, or Vue.js, preferably for DBT or other citizen-facing portals</li>\r\n	<li>Optimize applications for maximum speed, scalability, and accessibility.</li>\r\n	<li>Ensure the technical feasibility of UI/UX designs and propose innovative solutions.</li>\r\n	<li>Collaborate with back-end developers to integrate RESTful APIs and web services.</li>\r\n	<li>Validate user input on the client side and provide meaningful feedback.</li>\r\n	<li>Conduct thorough cross-browser and cross-device testing to ensure consistent user experience.</li>\r\n	<li>Maintain and improve existing codebases, refactoring for performance and maintainability.</li>\r\n	<li>Document front-end architecture, components, and styles for team reference.</li>\r\n	<li>Participate in team meetings, code reviews, and Agile/Scrum ceremonies.</li>\r\n	<li>Stay updated with emerging front-end technologies and best practices.</li>\r\n	<li>Participate in team meetings, code reviews, and brainstorming sessions.</li>\r\n	<li>Identify areas for process improvement and contribute to the enhancement of development workflows, tools, and methodologies, ensuring compliance with ISO 9001, ISO 20000, ISO 27001, and CMMI Level 5 standards.</li>\r\n	<li>Complete tasks assigned by PM, or other higher management officials within the given timeframe.</li>\r\n</ul>\r\n','','Front-end Developer','2025-10-15');
/*!40000 ALTER TABLE `careers` ENABLE KEYS */;
UNLOCK TABLES;

