INSERT INTO `contacts` VALUES (1,'karunakaran','karunakaran@kran.co.in','8098366025','Test','G',NULL,'2024-09-26 13:05:59'),(2,'karunakaran','karunakaran@kran.co.in','8098366025','Testing purpose','G',NULL,'2024-09-26 14:47:33'),(3,'Karunakaran','karunakaran1.dn@gmail.com','8098366025','Test','G',NULL,'2024-09-27 05:37:47'),(4,'Asan Mohamed K','asanmohamedkhansa1234@gmail.com','9003587148','Hlo Everyone,\r\nI\'m Asan Mohamed from Tirunelveli, Tamil Nadu and a recently graduated in BE Computer Science and Engineering. I hold the skills in Front End like HTML, CSS and Java Script, Programming languages as C, Python, SQL queries and the GIT version. I would like to get in touch with you for any Job Requirements and Internships','G',NULL,'2024-12-19 12:11:27'),(5,'Geet Nahata','nahatageet@gmail.com','7890148623','Kindly provide in detail about the project and its benefits ','','AFC','2024-12-26 12:26:03'),(6,'Nitesh raikwar ','niteshraikwar300@gmail.com','7804915887','Okknshshshshsjsksjushs','','SmartCampus','2025-01-01 15:41:25'),(7,'Vinay Lakkoju','vinaylakkoju17@gmail.com','9603043375','Application for Flutter Developer Position -Vinay Lakkoju \r\nDear Hiring Team,\r\n\r\nI hope this email finds you well.\r\n\r\nI am writing to express my interest in the Flutter Developer position at your esteemed company. With hands-on experience in Flutter and Dart, I have developed and maintained several high-quality mobile applications, ensuring efficient code and seamless user experiences.\r\n\r\nIn my previous roles as a Flutter Developer Intern at TS Bridge EDU and REAIDY.IO, I collaborated with UI/UX designers to translate wireframes into functional apps, integrated third-party APIs, and followed industry best practices for mobile development. Additionally, my recent project Check My Resume, an AI-powered resume optimizer, has garnered over 1,500 downloads.\r\n\r\nI am passionate about mobile development and constantly staying updated with the latest trends and technologies in the field. I am confident that my skills and dedication will allow me to contribute effectively to your development team and deliver high-quality results.\r\n\r\nI have attached my resume for your consideration. I look forward to the opportunity to discuss how I can contribute to your company.\r\n\r\nThank you for your time and consideration.\r\n\r\n\r\nBest regards,\r\nVinay Lakkoju\r\n9603043375\r\nMy Apps In Playstore:\r\nCHECK MY RESUME:-\r\n\r\nhttps://play.google.com/store/apps/details?id=com.vinaylakkoju.resume_analyzer\r\n\r\nPROMPT GPT:-\r\n\r\nhttps://play.google.com/store/apps/details?id=com.vinaylakkoju.flutter_gemini\r\n\r\nMy Resume:-\r\nhttps://drive.google.com/file/d/1FPlZ08XXhG2aHoZbu748EskmUmaH60ne/view?usp=drivesdk\r\n\r\nMy portfolio:-\r\nhttps://vinay-portfolio-1.web.app/\r\n','G',NULL,'2025-01-12 02:09:01'),(8,'Vinay Lakkoju','vinaylakkoju17@gmail.com','9603043375','Application for Flutter Developer Position -Vinay Lakkoju \r\nDear Hiring Team,\r\n\r\nI hope this email finds you well.\r\n\r\nI am writing to express my interest in the Flutter Developer position at your esteemed company. With hands-on experience in Flutter and Dart, I have developed and maintained several high-quality mobile applications, ensuring efficient code and seamless user experiences.\r\n\r\nIn my previous roles as a Flutter Developer Intern at TS Bridge EDU and REAIDY.IO, I collaborated with UI/UX designers to translate wireframes into functional apps, integrated third-party APIs, and followed industry best practices for mobile development. Additionally, my recent project Check My Resume, an AI-powered resume optimizer, has garnered over 1,500 downloads.\r\n\r\nI am passionate about mobile development and constantly staying updated with the latest trends and technologies in the field. I am confident that my skills and dedication will allow me to contribute effectively to your development team and deliver high-quality results.\r\n\r\nI have attached my resume for your consideration. I look forward to the opportunity to discuss how I can contribute to your company.\r\n\r\nThank you for your time and consideration.\r\n\r\n\r\nBest regards,\r\nVinay Lakkoju\r\n9603043375\r\nMy Apps In Playstore:\r\nCHECK MY RESUME:-\r\n\r\nhttps://play.google.com/store/apps/details?id=com.vinaylakkoju.resume_analyzer\r\n\r\nPROMPT GPT:-\r\n\r\nhttps://play.google.com/store/apps/details?id=com.vinaylakkoju.flutter_gemini\r\n\r\nMy Resume:-\r\nhttps://drive.google.com/file/d/1FPlZ08XXhG2aHoZbu748EskmUmaH60ne/view?usp=drivesdk\r\n\r\nMy portfolio:-\r\nhttps://vinay-portfolio-1.web.app/','G',NULL,'2025-01-12 02:09:46'),(9,'Sinan B H','sinanbh9605@gmail.com','9605793492','Dear Hiring Manager \r\n\r\nI hope this email finds you well. My name is Sinan B H, and I am writing to express my interest in the MERN Stack Developer position. As a recent graduate with a BSc in Computer Science and a certified full-stack developer, I am eager to bring my skills to your team.\r\n\r\nI have worked on team projects, including:\r\n\r\nTask Management System (doque): Contributed to creating user-friendly interfaces using React.js, implemented API integrations with Node.js, and ensured efficient database management with MongoDB.\r\nE-commerce Website for Furniture (PlushParadise): Designed and developed a fully responsive platform with dynamic product displays, secure backend APIs, and seamless database connectivity.\r\n\r\n\r\nThank you for considering my application. I look forward to the opportunity to connect.','C',NULL,'2025-01-16 03:59:28'),(10,'Shishir kanta Mohapatra','shishir.bbsr.odisha@gmail.com','9853926277','Wish to apply for Technical Support Engineer','G',NULL,'2025-03-24 05:57:19'),(11,'Sreekatrthikkj','sreekarthiksree2@gmail.com','8136901403','I need a job','','eMetier','2025-05-09 13:27:50');
