INSERT INTO `events` VALUES (1,'Providing financial advice, including cost reduction strategies, financial planning.','Our technology consulting services guide businesses through digital transformation, cloud adoption, and IT structure optimization. We help you leverage technology to drive innovation and efficiency.','Teleconference Dial-In Number: United States: 1-877-883-0383','Cloud Strategy, Cybersecurity, IT Infrastructure, Software Development Advisory.',NULL,'Technology Consulting','Workshop','2025-07-08 14:48:20','N','N','2025-07-08 22:10:00','fas fa-cloud','7012571125','2025-07-08 15:46:40'),(2,'Intensive hands-on program for public officials to adopt digital governance tools and best practices.','This bootcamp is designed to empower public officials with skills in e-Governance platforms, open data systems, and digital public service delivery. Sessions will include:\r\n- Digital ID integration\r\n- Open data dashboards\r\n- Paperless office workflows\r\n- Citizen service portals','Kerala Institute of Local Administration, Thrissur','Hands-on Labs, Case Studies, Live Demos',NULL,'Digital Governance Bootcamp','Workshop','2025-07-08 15:53:49','N','N','2025-08-09 10:00:00','fas fa-network-wired','support@cpart.co.in','2025-07-08 15:53:49'),(3,'Collaborate and co-create next-gen policy interventions for emerging societal challenges.','Bring together students, researchers, and bureaucrats to prototype solutions for:\r\n- Waste management\r\n- Digital grievance redressal\r\n- Migrant welfare\r\n- AI in public service delivery\r\n','C-PART Head Office, Thiruvananthapuram','Design Thinking, Agile Sprinting, Peer Review',NULL,'Policy Innovation Hackathon','Conference','2025-07-08 15:56:33','N','N','2025-08-16 10:30:00','fas fa-lightbulb','support@cpart.co.in','2025-07-08 15:56:33'),(4,'Roundtable discussion on reengineering bureaucratic systems for transparent governance.','Discussion topics:\r\n- Strengthening RTI frameworks\r\n- Simplification of service delivery rules\r\n- Performance appraisal systems for departments\r\nPanelists include top IAS officers and governance scholars.\r\n','Online - Zoom meeting','Data Visualization, Panel Discussion, Case Demonstrations','http://localhost:8081/events','Administrative Reforms Dialogue','Webinar','2025-07-08 15:58:04','N','N','2025-08-23 09:00:00','fas fa-university','support@cpart.co.in','2025-07-24 11:44:38');
/*!40000 ALTER TABLE `events` ENABLE KEYS */;
