DROP TABLE IF EXISTS `kran_projects`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `kran_projects` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `category` varchar(150) DEFAULT NULL,
  `title` varchar(500) DEFAULT NULL,
  `c_status` varchar(45) DEFAULT NULL,
  `service_con` varchar(150) DEFAULT NULL,
  `service_sddwm` varchar(150) DEFAULT NULL,
  `service_sdd` varchar(150) DEFAULT NULL,
  `service_pi` varchar(150) DEFAULT NULL,
  `service_oms` varchar(150) DEFAULT NULL,
  `service_dm` varchar(150) DEFAULT NULL,
  `service_am` varchar(45) DEFAULT NULL,
  `service_dbm` varchar(45) DEFAULT NULL,
  `service_tsu` varchar(45) DEFAULT NULL,
  `service_ccn` varchar(45) DEFAULT NULL,
  `service_pas` varchar(45) DEFAULT NULL,
  `sdescription` varchar(500) DEFAULT NULL,
  `c_description` varchar(5000) DEFAULT NULL,
  `description` varchar(10000) DEFAULT NULL,
  `department` varchar(150) DEFAULT NULL,
  `client` varchar(100) DEFAULT NULL,
  `image_path` varchar(150) DEFAULT NULL,
  `submitted_On` datetime DEFAULT NULL,
  `active_status` char(1) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=84 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;
