INSERT INTO `kran_seniors` VALUES (1,'Ajith Kumar','Chief Executive Officer','Management','KRAN is an IT Consultancy and Software Solution Provider organisation, with an exclusive focus on Government and Public Sector vertical in India. During our many engagements over the past 25 years, with various Government Departments and PSUs, the focus has been on the Reinvention & Transformation of eGovernance in the country','25','1994-01-01','Ajith.png','2024-08-26 12:54:10','A'),(2,'Maya Vijay','Chief Operating Officer','Management','KRAN is an IT Consultancy and Software Solution Provider organisation, with an exclusive focus on Government and Public Sector vertical in India. During our many engagements over the past 25 years, with various Government Departments and PSUs, the focus has been on the Reinvention & Transformation of eGovernance in the country','25','1997-01-01','0.03416697876896646@-@maya.png','2024-09-02 18:43:29','A'),(3,'Pradeep K S','Chief Marketing Officer','Management','KRAN is an IT Consultancy and Software Solution Provider organisation, with an exclusive focus on Government and Public Sector vertical in India. During our many engagements over the past 25 years, with various Government Departments and PSUs, the focus has been on the Reinvention & Transformation of eGovernance in the country','25','1996-01-01','Pradeep sir 2.png','2024-12-04 12:25:26','A'),(4,'Anil Kumar','Project Management','Others','KRAN is an IT Consultancy and Software Solution Provider organisation, with an exclusive focus on Government and Public Sector vertical in India. During our many engagements over the past 25 years, with various Government Departments and PSUs, the focus has been on the Reinvention & Transformation of eGovernance in the country','17','2007-10-26','0.953626853150496@-@Romi.png','2024-09-07 13:26:18','A'),(5,'Anand S V','Program Director','PD','KRAN is an IT Consultancy and Software Solution Provider organisation, with an exclusive focus on Government and Public Sector vertical in India. During our many engagements over the past 25 years, with various Government Departments and PSUs, the focus has been on the Reinvention & Transformation of eGovernance in the country','14','2010-09-20','0.888360865308802@-@anand.png','2024-09-06 10:58:13','A'),(6,'Riju V','Program Director','PD','KRAN is an IT Consultancy and Software Solution Provider organisation, with an exclusive focus on Government and Public Sector vertical in India. During our many engagements over the past 25 years, with various Government Departments and PSUs, the focus has been on the Reinvention & Transformation of eGovernance in the country','13','2011-01-05','Riju.png','2024-08-24 18:52:02','A'),(7,'Sujith Mohan M','Program Director','PD','KRAN is an IT Consultancy and Software Solution Provider organisation, with an exclusive focus on Government and Public Sector vertical in India. During our many engagements over the past 25 years, with various Government Departments and PSUs, the focus has been on the Reinvention & Transformation of eGovernance in the country','13','2011-04-05','0.8840032426028422@-@sujith.png','2024-09-06 10:58:24','A'),(8,'Romilal P','Program Director','PD','Nil','13','2011-07-18','Romi (4).png','2025-01-15 04:46:37','A'),(9,'Abhijith R V','Program Director','PD','Nil','12','2012-06-04','0.14255113021615373@-@Abhijit.png','2024-08-24 14:32:03','A'),(10,'Jeesha K S','Senior Accountent ','Others','NIl','10','2011-03-28','0.5865987127181356@-@jeesha.png','2024-08-24 10:43:00','D'),(11,'Syamraj','Lead Designer','Others','Nil','10','2012-08-06','Syam.png','2024-08-23 17:29:20','D');
