INSERT INTO `kran_solutions` VALUES (1,'Public Finance','ProbityFinancials','Y','Integrated Financial Management System','    <li style=\"text-align: left;\">Software Design & Development (Web & Mobile App)</li>    <li style=\"text-align: left;\">        Project Implementation</li>    <li style=\"text-align: left;\">        Operations and Maintenance Support</li>    <li style=\"text-align: left;\">        Maintenance Support</li>','<p style=\"text-align: left;\">Probity Financials is a standardized Financial Monitoring and Reporting System that serves as a Single Source of Truth for the financials of a state, improving decision-making, enhancing accountability, and ensuring compliance with financial regulations and standards. It consolidates all financial information requirements of the government into a single information database, ensuring data transparency for stakeholders and enabling them to make effective and informed decisions.</p><br>\r\n<p style=\"text-align: left;\">This solution encompasses all critical financial areas starting from Budget Preparation, Budget Modification and Distribution, Budget Control, Budget Execution, Debt and Audit Management etc. Probity Financials also facilitate various integrations with external applications to ensure seamless and efficient operations across various modules which improves decision-making, enhancing transparency, and maintaining consistency across all processes. </p>','<ul>\r\n    <li style=\"text-align: left;\">Consolidates all financial information into a single, unified database, serving as a comprehensive source of truth for the government’s financial data.</li>\r\n    <li style=\"text-align: left;\">\r\n        Provides standardized tools and processes for financial monitoring and reporting, ensuring consistency and accuracy across all financial activities.</li>\r\n    <li style=\"text-align: left;\">\r\n        Facilitates efficient budget planning, management, and tracking, allowing for real-time monitoring of expenditures and allocations.</li>\r\n    <li style=\"text-align: left;\">\r\n        Monitors and records revenue generation and expenditures, ensuring efficient management of public funds and resources.</li>\r\n    <li style=\"text-align: left;\">\r\n        Ensures compliance with financial regulations and standards through automated checks and audit trails, reducing the risk of errors and discrepancies.</li>\r\n    <li style=\"text-align: left;\">\r\n        Seamlessly integrates with other Govt. systems, such as procurement, RBI, PFMS, GSTN, NPS, Payroll, and tax management, ensuring a cohesive financial management ecosystem.</li>\r\n</ul>','fdf','fdfd','project-modal (1).jpg','2024-11-20 06:14:28','A'),(2,'Public Finance','AIMS','Y','Audit Information Management System','','<p style=\"text-align: left;\">Audit Information Management System is a comprehensive solution designed to automate the core functions of the Audit department, providing a seamless, end-to-end platform for managing the entire audit lifecycle. This system enhances operational transparency and ensures timely reporting and resolution of audit concerns.\r\n</p> <br>\r\n<p style=\"text-align: left;\">Key features and functionality of AIMS includes Collection and consolidation of Statements/Records, Audit calendar preparation, Team formation, Audit enquiry and collection of objective evidence, Recording of audit observations, Generation of audit reports, Tracking of audit findings to closure.​</p>','<ul>\r\n    <li style=\"text-align: left;\">End-to-end management of the entire audit lifecycle, from planning and execution to reporting and resolution tracking.</li>\r\n    <li style=\"text-align: left;\">\r\n        Centralized platform for handling all audit activities, ensuring consistency and efficiency across audits.</li>\r\n    <li style=\"text-align: left;\">\r\n        This solution facilitates the creation and management of the audit calendar, encompassing the scheduling of audits, and assignment of audit teams. This ensures a structured and organized approach to audit planning, enhancing efficiency and adherence to timelines.</li>\r\n    <li style=\"text-align: left;\">\r\n        Collection and consolidation of required statements, records, and objective evidence in a centralized repository.</li>\r\n    <li style=\"text-align: left;\">\r\n        Centralized observation database, enabling quick access and comprehensive review of audit results.</li>\r\n    <li style=\"text-align: left;\">\r\n        Generation of detailed audit reports, summarizing findings, observations, and recommendations.</li>\r\n    <li style=\"text-align: left;\">\r\n        Real-time tracking of audit findings, from identification to closure, ensuring effective follow-up and timely resolution.</li>\r\n    <li style=\"text-align: left;\">\r\n        Facility to integrate with external applications</li>\r\n</ul>','ew','ew',NULL,'2024-11-20 06:14:14','A'),(3,'Public Finance','Sirius','Y','Macro Fiscal Projection','','<p style=\"text-align: left;\">Sirius is a web-based system that covers the core functional areas of the Directorate of Economics and Statistics. The objective is to have an integrated Macro Fiscal Projection Solution with Metrics and Business Intelligence aligned to the Sustainable Development Goals (SDG). Leveraging the benefits of technology as an add-on to the well-organized existing statistical system at this departmental level will ensure the effective usage of the various data which are collected, and this will also form the input to the fiscal indicators of an effective long-term fiscal projection system. Long-term fiscal projections provide a basis to discuss the sustainability of current government policies.</p>','<ul><li style=\"text-align: left;\">Sirius offers a comprehensive platform for generating macroeconomic and fiscal projections. It combines statistical data with fiscal metrics to provide a cohesive and accurate long-term fiscal outlook.</li><li style=\"text-align: left;\">\r\nThe system is equipped with business intelligence tools that provide insights into economic and fiscal trends. It aligns these metrics with the Sustainable Development Goals (SDGs), ensuring that projections and analysis are consistent with global sustainability objectives.</li><li style=\"text-align: left;\">\r\nSirius leverages the existing statistical systems and integrates them into a unified platform. This approach ensures the effective use of collected data, enhancing the accuracy of fiscal indicators and economic models.</li><li style=\"text-align: left;\">\r\nBy using modern technology, Sirius enhances the capabilities of the Directorate of Economics and Statistics, transforming collected data into actionable insights. This ensures that policymakers and stakeholders have access to real-time, data-driven information.</li><li style=\"text-align: left;\">\r\nSirius ensures that its fiscal and economic projections are aligned with SDG targets, supporting the government in meeting its sustainability commitments while maintaining fiscal responsibility.</li></ul>','','',NULL,'2024-11-20 06:22:48','A'),(4,'Public Finance','Orion','Y','Loan Management System','','<p style=\"text-align: left;\">Orion is a comprehensive system designed to manage various instalment loans, deeds of trust, and an extensive client database with their payment records. The system streamlines all processes, from loan application to closure, and supports diverse loan types, including term loans, educational loans, and microfinance. It automates the meticulous and time-consuming bookkeeping tasks associated with loan servicing and collection, ensuring efficiency and accuracy throughout the loan management lifecycle.</p><br>\r\n<p style=\"text-align: left;\">Orion supports multiple repayment methods, including cash, cheque, and electronic payments. It accommodates deferrals in loan repayment installments by offering repayment holidays during the loan tenure and allows for the rescheduling of outstanding loan amounts, facilitating one-time settlements (OTS) for loan defaulters. Orion is an ideal solution for loan servicing, catering to organizations of any size with efficiency and flexibility.</p>','<ul>\r\n    <li style=\"text-align: left;\">Orion manages a wide range of instalment loans, deeds of trust, and client payment records, providing a unified system for tracking and managing loan portfolios.</li>\r\n    <li style=\"text-align: left;\">\r\n        The system optimizes every stage of the loan lifecycle, from the application process to loan closure, ensuring efficient and error-free operations.</li>\r\n    <li style=\"text-align: left;\">\r\n        It automates time-consuming tasks related to loan servicing and collection, reducing the administrative burden and improving accuracy in record-keeping.</li>\r\n    <li style=\"text-align: left;\">\r\n        Orion supports multiple repayment methods, including cash, cheque, and electronic payments, providing flexibility and convenience for clients.</li>\r\n    <li style=\"text-align: left;\">\r\n        The system offers repayment holidays and deferral options during the loan tenure, allowing customers to adjust their repayment schedules when needed. It also supports the rescheduling of outstanding loan amounts.</li>\r\n    <li style=\"text-align: left;\">\r\n        Orion facilitates OTS for loan defaulters, providing a mechanism for clients to settle outstanding loans efficiently.</li>\r\n</ul>','','',NULL,'2024-11-20 06:25:02','A'),(5,'Public Finance','CharMS','Y','Charitable Endowments Management System','','<p style=\"text-align: left;\">CharMS is a digital platform designed to efficiently manage information related to charitable endowments.  It supports the Government of India\'s initiative to facilitate the establishment of charitable endowments.  CharMS manages the core functions associated with endowment management, including public registration, endowment request submission, processing and approval of endowment requests, issuance of initial notifications, final vesting orders, creation and management of endowments, FD interest management, and the generation of MIS reports.</p>','<ul><li style=\"text-align: left;\">CharMS efficiently manages the entire lifecycle of charitable endowments, from the submission of requests to the finalization of vesting orders.</li><li style=\"text-align: left;\">\r\nThe platform is aligned with the Government of India\'s regulations, making it easier for the public to institute charitable endowments and ensuring compliance with established rules.</li><li style=\"text-align: left;\">\r\nThe system supports the management of securities accounts and fixed deposit (FD) interest, providing a secure and organized approach to handling financial aspects of endowments.</li><li style=\"text-align: left;\">\r\nCharMS offers comprehensive and accurate account statements, ensuring transparency and clarity for both administrators and donors.</li><li style=\"text-align: left;\">\r\nThe platform generates detailed MIS reports, offering insights into the status and performance of endowments, aiding in decision-making and reporting.</li><li style=\"text-align: left;\">\r\nWith a user-centric design, CharMS is accessible and easy to use, simplifying the management of charitable endowments for donors, administrators, and government officials alike. </li></ul>','','',NULL,'2024-11-20 06:26:16','A'),(6,'Public Finance','ProMIS','Y','Project Monitoring Information System','','<p style=\"text-align: left;\">ProMIS captures comprehensive project-related information, including general details, cost and funding details, funds received and released to executing agencies, as well as schedules and milestone tracking. Based on the captured data, it generates detailed dashboards and reports. The dashboard provides alerts on milestones, reviews, and other critical updates, along with graphical charts for analyzing the current project status effectively.</p>','<ul><li style=\"text-align: left;\">ProMIS captures detailed project information, including general details, cost specifics, funding sources, funds received, funds released, schedules and milestone tracking.</li><li style=\"text-align: left;\">\r\nDynamic dashboards that provide real-time alerts on project milestones, reviews, and other critical updates, ensuring that project managers and stakeholders are informed promptly.</li><li style=\"text-align: left;\">\r\nProMIS generates various reports based on the captured data, offering insights into project progress, financials, and performance metrics, which support effective decision-making.</li><li style=\"text-align: left;\">\r\nProMIS offers detailed tracking of project schedules and milestones, providing visibility into project timelines and ensuring that key deliverables are met.</li><li style=\"text-align: left;\">\r\nThe system effectively monitors and manages project funds, from the receipt of funding to the release of payments to executing agencies, ensuring financial transparency and accountability.</li><li style=\"text-align: left;\">\r\nAutomated alerts and notifications keep project teams informed of important deadlines, changes, and critical updates, enhancing proactive management and responsiveness.</li></ul>','','',NULL,'2024-11-20 06:31:14','A'),(7,'Public Finance','ReMIS','Y','Report Monitoring Information System','','<p style=\"text-align: left;\">ReMIS is designed for monitoring reports based on audits conducted in various Union and State government departments by the Controller and Auditor General. It includes sub-modules such as CAG Reports, Inspection Reports, and Policy Recommendations, ensuring comprehensive oversight and management of audit outcomes.</p>','<p style=\"text-align: left;\">Centralized audit report management, categorization, progress tracking, automated reminders, policy monitoring, security, and role-based access.</p>\r\n<ul>\r\n    <li style=\"text-align: left;\">Centralized database to store and manage all audit reports, policy recommendations, and inspection reports generated by internal and external bodies</li>\r\n    <li style=\"text-align: left;\">\r\n        Tracks and manages insights from CAG audit findings, offering detailed reporting and facilitating corrective action follow-up.</li>\r\n    <li style=\"text-align: left;\">\r\n        Enables effective tracking of inspection outcomes, ensuring any identified issues are monitored and addressed in a timely manner.</li>\r\n    <li style=\"text-align: left;\">\r\n        Supports departments in maintaining accountability by tracking the status of actions taken on audit findings, ensuring regulatory compliance and governance.</li>\r\n    <li style=\"text-align: left;\">\r\n        Automated alerts and reminders for pending actions or upcoming deadlines help ensure timely follow-up on audit recommendations and compliance requirements and escalating unresolved issues to higher authorities, if necessary.</li>\r\n    <li style=\"text-align: left;\">\r\n        Robust security measures to protect sensitive information and role-based access to authorized users.</li>\r\n</ul>','','',NULL,'2024-11-20 06:33:08','A'),(8,'Public Finance','FIMS','Y','Financial Inspection Management System','','<p style=\"text-align: left;\">The Financial Inspection Management System (FIMS) is a comprehensive solution designed to streamline and manage all aspects of inspection processes within an organization. FIMS provides a structured approach to inspection management, ensuring thorough oversight, tracking, and reporting of inspection activities.</p>','<ul><li style=\"text-align: left;\">Facilitates the structured preparation, review, and approval of inspection schedules, ensuring inspections are conducted in a timely and organized manner.</li><li style=\"text-align: left;\">\r\nGenerates a wide range of parameterized reports that allow organizations to track trends, assess compliance, and analyze inspection data effectively</li><li style=\"text-align: left;\">\r\nEnables the generation of thorough inspection reports and action-taken reports, capturing findings, corrective actions, and follow-up tasks, promoting accountability.</li></ul>','','',NULL,'2024-11-20 06:34:13','A'),(9,'Permits, Licensing & Compliance','Phoenix','Y','e-Regulation System','','<p style=\"text-align: left;\">Phoenix is an integrated solution designed to automate the core functional activities of departments responsible for licensing, law compliance, and statutory reporting. The system streamlines and enhances efficiency across all stages of the licensing process, from issuance to renewal and compliance enforcement.</p><br>\r\n<p style=\"text-align: left;\">Phoenix is a comprehensive licensing and compliance management solution that supports departments in maintaining regulatory standards, enhancing transparency, and ensuring effective governance across licensing activities.</p>','<ul><li style=\"text-align: left;\">Covers the entire lifecycle of licensing activities, including issuance, renewal, amendment, transfer, and generation of duplicate licenses, promoting seamless workflow and process standardization.</li><li style=\"text-align: left;\">\r\nProvides tools to monitor adherence to regulations and enforce compliance, ensuring that licensees meet all statutory requirements.</li><li style=\"text-align: left;\">\r\nTracks license expiry and sends timely renewal reminders, reducing administrative effort and minimizing risk of non-compliance.</li><li style=\"text-align: left;\">\r\nSimplifies the process of making modifications to existing licenses and transferring licenses between parties, ensuring data accuracy and regulatory alignment.</li><li style=\"text-align: left;\">\r\nEnables automated tracking and submission of statutory returns, helping departments uphold compliance with legal and regulatory frameworks.</li><li style=\"text-align: left;\">\r\nStores and manages all license-related documents in a secure, centralized repository, ensuring easy retrieval and data integrity.</li><li style=\"text-align: left;\">\r\nEasy and seamless integration with external applications.</li><li style=\"text-align: left;\">\r\nOnline submission of Drawings for Factories Plan Approval.</li><li style=\"text-align: left;\">\r\nAuto fee calculation and Online Payment Transaction.</li></ul>','','',NULL,'2024-11-20 06:39:45','A'),(10,'Permits, Licensing & Compliance','Helix','Y','Welfare Management System','','<p style=\"text-align: left;\">Helix is a comprehensive Welfare Management System tailored to manage and deliver benefits effectively to registered workers in the unorganized sector. It enables efficient administration of welfare programs, ensuring that eligible individuals receive the support they are entitled to.</p><br>\r\n<p style=\"text-align: left;\">\r\n    This Welfare Management System empowers welfare boards to implement and monitor welfare programs efficiently, enabling the upliftment of workers in the unorganized sector and reinforcing their role in nation-building.</p>','<ul><li style=\"text-align: left;\">Manages the registration of workers in the unorganized sector, creating a centralized database for accurate beneficiary tracking and eligibility verification.</li><li style=\"text-align: left;\">\r\nEach registered worker receives a unique identification number, linked to their personal and welfare-related information, ensuring clear and accurate identification.</li><li style=\"text-align: left;\">\r\nAutomates the delivery of various benefits, ensuring timely and transparent access to financial support, healthcare, education, and other welfare services.</li><li style=\"text-align: left;\">\r\nProvides detailed reports on scheme implementation, fund utilization, and beneficiary coverage, ensuring compliance and fostering transparency in welfare management.</li><li style=\"text-align: left;\">\r\nEnsures that all worker data and welfare transactions are securely stored, maintaining privacy and integrity while supporting effective monitoring.</li></ul>','','',NULL,'2024-11-20 06:41:07','A'),(11,'General Administration','Stage','Y','File Monitoring and Management Solution','','<p style=\"text-align: left;\">Stage is a comprehensive, end-to-end File Monitoring and Management Solution developed to streamline and manage the routine processes within a government establishment. This solution efficiently supports the complete workflow of document handling, including Receipt and Registration of Inward/Dak, Filing and Note Submission, Submission to Higher Authorities, Return to Section and Draft Approval, Issuance of Correspondence.  Stage is designed to digitize and simplify the workflow within government offices, enhancing efficiency, transparency, and accountability in document management processes.</p>','<ul><li style=\"text-align: left;\">Stage provides an end-to-end solution for tracking files from the initial receipt to final correspondence, ensuring full visibility and accountability throughout the document\'s lifecycle.</li><li style=\"text-align: left;\">\r\nAutomates the registration and management of all incoming communications, ensuring quick access and organized record-keeping for government offices.</li><li style=\"text-align: left;\">\r\nFacilitates seamless submission of notes and routing of files to higher authorities, supporting faster approvals and decision-making processes.</li><li style=\"text-align: left;\">\r\nStreamlines the return of files to relevant sections and enables efficient draft approvals, reducing delays in document processing.</li><li style=\"text-align: left;\">\r\nAutomates the creation and issuance of final correspondence, ensuring timely and accurate communication with minimal manual intervention.</li><li style=\"text-align: left;\">\r\nStage’s digital workflow provides a transparent process with comprehensive audit trails, making it easy to track file movement and responsible authorities at each stage.</li></ul>','','',NULL,'2024-11-20 06:56:36','A'),(12,'General Administration','Edge','Y','Human Resource Management System','','<p style=\"text-align: left;\">Edge is a comprehensive Human Resources Management System (HRMS) developed to streamline and optimize HR activities within organizations. This system offers robust capabilities, including Employee Tracking, Skill Management, Salary Administration, Achievement Records.\r\n</p><br>\r\n<p style=\"text-align: left;\">Edge also empowers employees to verify and update their personal information, fostering data accuracy and reducing administrative workload. This system is ideal for organizations looking to enhance HR efficiency, data accuracy, and employee engagement.</p>','<ul><li style=\"text-align: left;\">Provides a centralized system for tracking employee records, career progression, and key employment data, offering a complete view of the workforce.</li><li style=\"text-align: left;\">\r\nEnables the systematic management of employee skills, helping organizations leverage internal talent and identify skill gaps for targeted development.</li><li style=\"text-align: left;\">\r\nAutomates payroll processes, ensuring accurate and timely salary disbursement, reducing manual errors, and increasing payroll efficiency.</li><li style=\"text-align: left;\">\r\nMaintains detailed records of employee achievements and performance, supporting fair and consistent evaluations and career advancement planning.</li><li style=\"text-align: left;\">\r\nAllows employees to verify and update their personal information, reducing administrative tasks for HR staff and enhancing data accuracy.</li><li style=\"text-align: left;\">\r\nWith up-to-date employee information and streamlined processes, Edge supports compliance with regulatory requirements and improves overall data integrity.</li></ul>','','',NULL,'2024-11-20 06:57:55','A'),(13,'General Administration','Smartnet','Y','Intra-Organization Communication and Collaboration Suite','','<p style=\"text-align: left;\">SmartNet is an intra-organizational communication and collaboration suite designed to facilitate seamless interaction among employees and enhance organizational efficiency. By enabling easy sharing and access to common information, SmartNet serves as the primary communication channel within the office environment, ensuring that crucial information remains accessible even in an individual’s absence.</p>','<ul>\r\n    <li style=\"text-align: left;\">Provides a unified space for all employee communications, ensuring clear, streamlined messaging and organization-wide announcements.</li>\r\n    <li style=\"text-align: left;\">\r\n        Allows employees to share and access essential information and documents with ease, promoting transparency and continuity across the organization.</li>\r\n    <li style=\"text-align: left;\">\r\n        Equipped with tools that enable real-time collaboration, enhancing teamwork and productivity in project coordination and task management.</li>\r\n    <li style=\"text-align: left;\">\r\n        Ensures that critical information remains accessible, preventing work disruptions even when key personnel are unavailable.</li>\r\n    <li style=\"text-align: left;\">\r\n        Facilitates smoother workflows and improved efficiency, creating a more connected, communicative, and responsive workplace environment.</li>\r\n</ul>','','',NULL,'2024-11-20 07:02:58','A'),(14,'General Administration','Probity','Y','Double Entry Financial Accounting System','','<p style=\"text-align: left;\">Probity is a comprehensive financial accounting solution designed to automate essential financial functions based on the double-entry accounting system. Tailored specifically for public sector units, Probity enhances the efficiency of financial management by streamlining key processes, including Record Maintenance, Financial Statement Preparation, Result Comparison, Informed Decision-Making, Legal Evidence and Information sharing.</p><br>\r\n<p style=\"text-align: left;\">Probity effectively records, monitors, and manages both accounting and financial data, providing swift and convenient access to information. With Probity, balance discrepancies become a thing of the past, empowering public sector units with precise, real-time financial data to support sustainable governance.</p>','<ul><li style=\"text-align: left;\">Automates financial management tasks using the double-entry accounting system, ensuring accuracy and reliability in financial records.</li><li style=\"text-align: left;\">\r\nDesigned specifically for the unique needs of public sector units, supporting government accountability and transparency in financial operations.</li><li style=\"text-align: left;\">\r\nSimplifies record-keeping, making it easy to maintain comprehensive and accurate financial records for audits and legal requirements.</li><li style=\"text-align: left;\">\r\nAutomates financial statement preparation, enabling easy result comparisons to facilitate informed decision-making.</li><li style=\"text-align: left;\">\r\nAutomates financial statement preparation, enabling easy result comparisons to facilitate informed decision-making.</li><li style=\"text-align: left;\">\r\nFacilitates seamless information sharing with relevant parties, ensuring timely updates and promoting transparency.</li></ul>','','',NULL,'2024-11-20 07:01:27','A'),(15,'General Administration','Monitor','Y','Contract Performance Monitoring System','<ul><li style=\"text-align: left;\">Consultancy</li>    <li style=\"text-align: left;\">Software Design & Development </li>    <li style=\"text-align: left;\">Project Implementation</li>    <li style=\"text-align: left;\">Operations and Maintenance Support</li></ul>','<p style=\"text-align: left;\">The Contract Performance Monitoring System manages the information related to the contractual employees of an organization. It includes details such as contract information, resource verification, roster preparation, attendance tracking, and payment details associated with the contract. This system ensures the effective and efficient management of contracts throughout their lifecycle.</p>','    <ul>\r\n        <li style=\"text-align: left;\">Real-Time Monitoring and Tracking of Contract Performance, monitor compliance with contractual obligations etc.</li>\r\n        <li style=\"text-align: left;\">\r\n            Automated Alerts and Notifications for approaching deadlines, potential risks, budget thresholds, and compliance issues.</li>\r\n        <li style=\"text-align: left;\">\r\n            Timely intervention to address performance concerns or non-compliance</li>\r\n        <li style=\"text-align: left;\">\r\n            Centralized Document Management for storing and managing all contract-related documents, including agreements, amendments, performance records, and communication logs</li>\r\n        <li style=\"text-align: left;\">\r\n            Comprehensive Dashboard and Reporting displaying contract performance metrics, compliance status, and financial details.</li>\r\n        <li style=\"text-align: left;\">\r\n            Facilitates data-driven decisions regarding renewals, contract amendments, or terminations.</li>\r\n        <li style=\"text-align: left;\">\r\n            Tracks contract expenditures, ensuring adherence to budget and preventing cost overruns.</li>\r\n        <li style=\"text-align: left;\">\r\n            Can be customized and scaled according to the organization’s specific needs.</li>\r\n    </ul>','','',NULL,'2024-10-10 16:31:33','A'),(16,'General Administration','GAdmin','Y','General Administration Management System','','<p style=\"text-align: left;\">GAdmin is a sophisticated monitoring and decision support system designed to empower administrators with comprehensive oversight across various operational areas. This system efficiently manages Purchase Orders and Stock Management, Asset Tracking and Vehicle Management, Resource Allocation and Project Progress Monitoring, Utility Payment Oversight, Hostel and Guest House Management, Court Cases and Estate Management and Grievance Resolution.</p><br>\r\n<p style=\"text-align: left;\">GAdmin stands as a vital tool for administrators, delivering effective monitoring and decision support to enhance organizational operations and service delivery.</p>','<ul><li style=\"text-align: left;\">Efficiently manages purchase orders and inventory levels, ensuring streamlined procurement and optimal stock control.</li><li style=\"text-align: left;\">\r\nProvides real-time asset tracking and comprehensive fleet management, optimizing resource utilization and maintenance schedules.</li><li style=\"text-align: left;\">\r\nFacilitates effective resource allocation and real-time monitoring of project milestones to ensure timely and cost-effective project completion.</li><li style=\"text-align: left;\">\r\nEnables structured utility payment management, preventing service disruptions and promoting financial discipline.</li><li style=\"text-align: left;\">\r\nStreamlines hostel and guest house management, from bookings to maintenance, ensuring smooth guest experiences.</li><li style=\"text-align: left;\">\r\nSupports tracking of court cases and estate assets, ensuring compliance and organized records for effective oversight.</li><li style=\"text-align: left;\">\r\nProvides a structured framework for grievance handling and resolution, enhancing transparency and accountability within the organization.</li></ul>','','',NULL,'2024-11-20 07:04:57','A'),(17,'Enterprise Resource Planning','SmartZone','Y','ERP Class Solution for SEZs & Industrial Parks','<ul>    <li style=\"text-align: left;\">Consultancy</li>    <li style=\"text-align: left;\">Software Design & Development </li>    <li style=\"text-align: left;\">Project Implementation</li>    <li style=\"text-align: left;\">Operations and Maintenance Support</li>    <li style=\"text-align: left;\">Integrations</li>    <li style=\"text-align: left;\">Cloud Hosting</li>    <li style=\"text-align: left;\">Security Audit</li></ul>','<p style=\"text-align: left;\">SmatZone is a comprehensive ERP Class Solution for the automation of the Key Functional, Administrative, Financial and Managerial Areas of Special Economic Zone (SEZ)/Industrial Parks. SmartZone can be used by different categories of SEZ includes: Free Trade Zones (FTZs); Export Processing Zones (EPZs); Free Zones (FZs); Industrial Parks/Industrial Estates (IEs); Free ports; Urban enterprise zones</p>','<ul>\r\n    <li style=\"text-align: left;\">The workflow automation and real time data access will enhance efficiency. </li>\r\n    <li style=\"text-align: left;\">\r\n        Real time monitoring by using digital records will improve transparency.</li>\r\n    <li style=\"text-align: left;\">\r\n        Automated compliance check and centralized reporting will streamline regulatory compliance. </li>\r\n    <li style=\"text-align: left;\">\r\n        Digital services and quick response system will offer good customer service and experience.</li>\r\n    <li style=\"text-align: left;\">\r\n        Data security measures and secure financial transactions will ensure security and compliance.</li>\r\n    <li style=\"text-align: left;\">\r\n        Timely tracking of Letter of Award end dates, contract expiry, bank guarantee, deposits, permission requests etc., through alerts and notifications. </li>\r\n    <li style=\"text-align: left;\">\r\n        Easy tracking of changes in rates and penalties.</li>\r\n    <li style=\"text-align: left;\">\r\n        Access to detailed history of existing unit instantly.</li>\r\n    <li style=\"text-align: left;\">\r\n        Streamlined handling of multiple contracts.</li>\r\n    <li style=\"text-align: left;\">\r\n        Effortless management of vendor contracts.</li>\r\n    <li style=\"text-align: left;\">\r\n        Detailed information on dashboards and custom report generation is an added benefit.</li>\r\n</ul>','','',NULL,'2024-10-10 16:35:52','A'),(18,'Enterprise Resource Planning','SmartOffice','Y','ERP Class Solution for Smarter Governance','','<p style=\"text-align: left;\">Smart Office is an advanced ERP (Enterprise Resource Planning) solution designed to streamline and integrate the key administrative functions within government departments. This comprehensive system offers a centralized, unified platform to manage various administrative processes, promoting efficiency, transparency, and ease of access.</p><br>\r\n<p style=\"text-align: left;\">It encompasses advanced components, including File Processing, Human Resources Management, Single Entry-based Financial Accounting, an Intra-Office Communication and Collaboration Suite, along with various tools for routine general administration.</p>','<ul>\r\n    <li style=\"text-align: left;\">Simplifies the handling, tracking, and processing of files within the department, ensuring efficient document management and reducing administrative delays.</li>\r\n    <li style=\"text-align: left;\">\r\n        Automates human resource functions such as employee records, payroll, leave management, performance tracking, and recruitment, enhancing workforce management.</li>\r\n    <li style=\"text-align: left;\">\r\n        Streamlines financial processes with single-entry accounting, ensuring accurate financial records, simplifying budgeting, and facilitating easy fund management.</li>\r\n    <li style=\"text-align: left;\">\r\n        Addresses routine administrative tasks such as scheduling, inventory management, and procurement, automating workflows to improve efficiency and reduce manual efforts.</li>\r\n    <li style=\"text-align: left;\">\r\n        SmartOffice covers all key administrative areas within a government department, reducing manual work, ensuring consistency, and optimizing departmental workflows.</li>\r\n    <li style=\"text-align: left;\">\r\n        Serves as a decision-support tool, providing real-time insights and data analytics to administrators, enabling informed decision-making and better governance.</li>\r\n</ul>','','',NULL,'2024-11-20 06:42:59','A'),(19,'Enterprise Resource Planning','Saarathi','Y','An ERP Class Solution for State Road Transport Corporations','','<p style=\"text-align: left;\">Saarathi is a comprehensive suite of interdependent applications designed to automate and optimize the core functional, administrative, financial, and managerial operations of Road Transport Corporations (RTCs). The system integrates key areas of RTC management, facilitating efficient and streamlined operations. By automating essential tasks, Saarathi enables RTCs to operate as a cohesive and well-managed entity.</p><br>\r\n<p style=\"text-align: left;\">Saarathi supports the efficient functioning of RTCs by automating essential tasks and providing real-time insights for informed decision-making, enhancing both customer service and operational performance.</p>','<ul><li style=\"text-align: left;\">Automates passenger bookings and reservations, providing a seamless online experience and improving operational efficiency.</li><li style=\"text-align: left;\">\r\nEnsures effective management of RTC resources and materials, optimizing stock levels, procurement, and distribution.</li><li style=\"text-align: left;\">\r\nOptimizes vehicle scheduling and route planning, ensuring cost-effective operations and efficient travel routes based on demand and traffic conditions.</li><li style=\"text-align: left;\">\r\nFacilitates the dynamic management of fare structures, ensuring accurate and transparent fare calculation based on various parameters like distance, zones, and discounts.</li><li style=\"text-align: left;\">\r\nAutomates the tracking, maintenance, and management of the fleet, ensuring efficient utilization, timely vehicle servicing, and performance monitoring.</li><li style=\"text-align: left;\">\r\nGenerates routine operational, financial, and performance reports automatically, enabling real-time decision-making and improved management oversight.</li><li style=\"text-align: left;\">\r\nSaarathi integrates key areas such as reservations, inventory, routes, fares, and fleet management into a cohesive system, streamlining RTC operations and improving overall efficiency.  </li></ul>','','',NULL,'2024-11-20 06:44:21','A'),(20,'Enterprise Resource Planning','Galaxy','Y','ERP Class Solution for Smarter Governance for PSUs','','\r\n<p style=\"text-align: left;\">“Galaxy” is an ERP solution for Public Sector Units, supporting seamless access across modules through a centralized server. This setup ensures organizational interconnectivity and offers administrators a robust decision-support and monitoring tool with flexible customization options\r\n</p><br>\r\n<p style=\"text-align: left;\">\"Galaxy,\" is an integrated platform designed to streamline administrative functions across Public Sector Units (PSUs). It encompasses advanced components, including File Processing, Human Resources Management, Double Entry-based Financial Accounting, an Intra-Office Communication and Collaboration Suite, along with various tools for routine general administration. Galaxy is a robust, scalable solution, ideal for PSUs seeking comprehensive automation and streamlined management across their administrative functions.</p>','<ul>\r\n    <li style=\"text-align: left;\">Galaxy is an ERP-class solution that fully integrates key administrative functions for Public Sector Units (PSUs), offering a streamlined approach to manage various operational areas.</li>\r\n    <li style=\"text-align: left;\">\r\n        All modules within Galaxy are accessible through a single login, enhancing ease of use and ensuring a seamless experience across departments.</li>\r\n    <li style=\"text-align: left;\">\r\n        The platform operates on a centralized server, which facilitates interconnectivity across different sections of an organization and ensures data consistency and security.</li>\r\n    <li style=\"text-align: left;\">\r\n        Efficient management of digital files and documentation, ensuring fast and secure document flow within the organization</li>\r\n    <li style=\"text-align: left;\">\r\n        Comprehensive HR tools to manage recruitment, attendance, payroll, performance evaluation, and employee records.</li>\r\n    <li style=\"text-align: left;\">\r\n        Accurate and transparent financial management based on the double-entry bookkeeping system, meeting accounting standards.</li>\r\n    <li style=\"text-align: left;\">\r\n        Tools that enable real-time communication and collaboration, supporting teamwork and efficiency.</li>\r\n    <li style=\"text-align: left;\">\r\n        Galaxy can be tailored to meet the specific needs and preferences of different PSUs, allowing for adaptation to unique organizational requirements.</li>\r\n    <li style=\"text-align: left;\">\r\n        Galaxy acts as an effective decision-support tool, providing administrators with data-driven insights and real-time analytics to aid strategic decision-making.</li>\r\n</ul>','','',NULL,'2024-11-20 06:45:40','A'),(21,'Enterprise Resource Planning','GalaxyALMS','Y','Application Life Cycle Management System','','<p style=\"text-align: left;\">GalaxyALMS is an integrated suite designed to facilitate comprehensive monitoring and management across the entire software development life cycle. Serving as a single source of truth for all project and portfolio information, the solution meticulously captures every activity and sub-activity from the inception of a project. GalaxyALMS is aligned with CMMI Level 5 best practices, ensuring adherence to the highest standards in software development and process maturity.</p><br>\r\n<p style=\"text-align: left;\">This project management solution supports software projects from the planning stage through to implementation, providing effective tools for accurate estimation, schedule compliance tracking, and resource optimization. GalaxyALMS facilitates complete oversight and control throughout the entire development life cycle, ensuring efficient project execution and management.</p>','<ul><li style=\"text-align: left;\">GalaxyALMS is a complete project management solution that supports the entire software development life cycle, from initial planning to final implementation, ensuring continuity and comprehensive oversight.</li><li style=\"text-align: left;\">\r\nActing as a single source of truth, GalaxyALMS consolidates all project and portfolio-related information, enabling easy access to real-time data across teams and stakeholders.</li><li style=\"text-align: left;\">\r\nGalaxyALMS is aligned with CMMI Level 5 best practices, which ensures high standards in process maturity, quality management, and continuous improvement throughout the development cycle.</li><li style=\"text-align: left;\">\r\nThe system captures all activities and sub-activities within each project, providing in-depth tracking and accountability at every stage of development.</li><li style=\"text-align: left;\">\r\nGalaxyALMS assists with accurate estimation and schedule adherence, as well as resource optimization, helping project managers meet deadlines and efficiently allocate resources.</li><li style=\"text-align: left;\">\r\nThe platform offers real-time monitoring and insightful reports, equipping project teams with the tools to identify issues early and make data-driven adjustments.</li><li style=\"text-align: left;\">\r\nGalaxyALMS fosters collaboration among project teams by centralizing communications, improving visibility across project phases, and providing a unified platform for updates and progress tracking.</li></ul>','','',NULL,'2024-11-20 06:54:10','A'),(22,'Enterprise Resource Planning','GalaxyMED','Y','An ERP Class Solution for Medical Services Corporations','','<p style=\"text-align: left;\">GalaxyMed is a comprehensive ERP solution meticulously crafted to address the diverse functional and administrative needs of Medical Services Corporations. This robust platform is designed to optimize critical operational workflows and ensure seamless management of resources across the organization.</p><br>\r\n<p style=\"text-align: left;\">GalaxyMed supports functional activities such as Drug Procurement and Distribution, Equipment Procurement and Maintenance, Construction Management etc. and administrative activities such as HR management, financial accounting, Court case management, File Processing, Fleet Management, Intra Office Communication etc.</p>','<ul><li style=\"text-align: left;\">GalaxyMed is a purpose-built ERP solution designed specifically for the unique needs of Medical Services Corporations, integrating all core functional and administrative areas into a single, unified platform.</li><li style=\"text-align: left;\">\r\nStreamlines the entire lifecycle of drug procurement, inventory management, and distribution, ensuring compliance with regulatory standards, optimized stock levels, and timely replenishment.</li><li style=\"text-align: left;\">\r\nManages the acquisition, deployment, and maintenance schedules for medical equipment, safeguarding operational continuity and supporting compliance with safety protocols.</li><li style=\"text-align: left;\">\r\nProvides project management tools to oversee medical infrastructure projects, facilitating scheduling, cost tracking, and resource allocation for timely project completion.</li><li style=\"text-align: left;\">\r\nFeatures an extensive HR module to manage employee records, payroll, and performance evaluations, paired with a robust financial accounting system to ensure transparency, compliance, and efficient financial reporting.</li><li style=\"text-align: left;\">\r\nOffers Court Case Management to track ongoing legal cases, ensuring timely documentation and updates on case proceedings, which is critical for risk management and compliance.     </li><li style=\"text-align: left;\">\r\nEnables efficient fleet operation and maintenance, optimizing asset utilization and lowering operational costs while supporting timely service delivery.</li><li style=\"text-align: left;\">\r\nPromotes effective collaboration and communication within the organization through secure, real-time messaging and task management.</li></ul>','','',NULL,'2024-11-20 06:55:32','A'),(23,'Direct Benefit Transfer','Optimus','Y','Fund & Benefit Management System','','<p style=\"text-align: left;\">The Direct Benefit Transfer (DBT) program, launched by the Government of India, represents a transformative approach to distributing benefits from various social welfare schemes, such as subsidies and scholarships, directly into beneficiaries\' bank accounts. This initiative is primarily focused on enhancing the efficiency and transparency of the government’s distribution mechanism.</p><br>\r\n<p style=\"text-align: left;\">DBT has been instrumental in redesigning the traditional practices within welfare systems, facilitating the direct, timely, and secure transfer of funds to beneficiaries. By bypassing intermediaries, it mitigates the risks of leakages, fraud, and duplication, thereby ensuring that intended beneficiaries receive their entitled benefits without unnecessary delays. This system not only expedites the delivery of funds but also upholds the integrity of government welfare programs, reinforcing trust and efficacy in the administration of social services.</p><br>\r\n<p style=\"text-align: left;\">Optimus is a system which serves as a robust digital platform for implementing Direct Benefit Transfer (DBT) to eligible beneficiaries across various segments of society. It enables the prompt disbursement of financial assistance to diverse groups, including construction workers, migrant workers, agricultural laborers, and students abroad. The platform is integrated with a banking gateway interface, allowing for swift, secure, and efficient fund transfers directly to beneficiaries’ bank accounts. By facilitating timely financial support, this system is a critical tool in enhancing the delivery of welfare benefits, ensuring they reach those in need with minimal delay and maximum transparency.</p>','<ul><li style=\"text-align: left;\">Facilitates quick and direct financial assistance transfers to beneficiaries’ bank accounts, eliminating intermediaries and reducing delays.</li><li style=\"text-align: left;\">\r\nEnsures full visibility into fund transfers, minimizing opportunities for fraud, leakage, and duplication, and promoting accountability.</li><li style=\"text-align: left;\">\r\nAllows targeted disbursement to specific beneficiary groups, such as construction workers, migrant workers, students abroad, and farmers, supporting a wide array of welfare schemes.</li><li style=\"text-align: left;\">\r\nIncludes seamless integration with banking systems for real-time fund transfers, with secure, automated reconciliation processes.</li><li style=\"text-align: left;\">\r\nUtilizes Aadhaar or other identification systems to authenticate beneficiaries, ensuring that benefits reach the rightful recipients.</li><li style=\"text-align: left;\">\r\nReduces administrative costs and complexities by simplifying distribution, eliminating paper-based processes, and reducing manual handling.</li><li style=\"text-align: left;\">\r\nDesigned to accommodate a wide range of social welfare schemes, with scalability to manage large numbers of beneficiaries across multiple sectors.</li><li style=\"text-align: left;\">\r\nIncorporates robust data security measures to protect beneficiary information and ensure compliance with regulatory and privacy standards.</li><li style=\"text-align: left;\">\r\nProvides a streamlined interface for administrators to track, monitor, and report on disbursements, allowing for improved oversight and decision-making.</li></ul>','','',NULL,'2024-11-20 07:08:20','A'),(24,'Others','ARAM','Y','Automated Repayment and Allotment Monitoring','','<p style=\"text-align: left;\">ARAM is a comprehensive solution for the allotment and repayment monitoring of units within industrial parks. It comprises three core modules: Allotment, Repayment, and Billing. Together, these modules enable efficient management of industrial park allotments, enhance financial oversight, and ensure accurate billing and repayment tracking.</p>','<ul>\r\n    <li style=\"text-align: left;\">Tracks and manages applicant information, nature of business, and payment details, ensuring a streamlined allotment process for industrial park units.</li>\r\n    <li style=\"text-align: left;\">\r\n        Allows for easy tracking of repayments from allotted units, helping to ensure timely collections and reduce the risk of overdue payments.</li>\r\n    <li style=\"text-align: left;\">\r\n        Generates monthly bills for each allotted unit, simplifying the billing process and reducing manual errors, which leads to greater billing accuracy and consistency.</li>\r\n    <li style=\"text-align: left;\">\r\n        Provides a unified platform that consolidates allotment, repayment, and billing data, enhancing visibility and control for administrators.</li>\r\n    <li style=\"text-align: left;\">\r\n        Offers flexible reporting options, enabling users to generate detailed reports for financial tracking, allotment status, and repayment schedules.</li>\r\n    <li style=\"text-align: left;\">\r\n        Designed with an intuitive interface, making it easy for administrators to manage data, track payments, and monitor allotments effectively.</li>\r\n    <li style=\"text-align: left;\">\r\n        Enhances transparency and accountability in financial transactions related to unit allotment and repayments within industrial parks.</li>\r\n    <li style=\"text-align: left;\">\r\n        Capable of handling a large number of units and applications, making it suitable for industrial parks of various sizes.</li>\r\n</ul>','','',NULL,'2024-11-20 07:13:30','A'),(25,'Others','Edify','Y','Training Administration System','','<p style=\"text-align: left;\">Edify is a comprehensive Training Management solution designed to automate the core functions involved in managing training programs within an organization. Suitable for any organization conducting customized training programs or scheduled short-term and long-term courses, Edify operates based on a pre-defined calendar.</p><br>\r\n<p style=\"text-align: left;\">This innovative solution enables organizations to streamline the administration of training programs, supporting the entire lifecycle of training from course creation through execution to closure. Edify facilitates efficient planning and optimal utilization of resources, ensuring that training operations are organized, effective, and aligned with organizational objectives. It empowers organizers to manage all aspects of their training programs seamlessly, enhancing the overall effectiveness and operational efficiency of training management.</p>','<ul><li style=\"text-align: left;\">Supports the complete lifecycle of training programs, including course creation, execution, and closure, ensuring streamlined administration.</li><li style=\"text-align: left;\">\r\nAutomates essential functions, reducing manual work in scheduling, resource allocation, attendance tracking, and reporting, thus increasing efficiency.</li><li style=\"text-align: left;\">\r\nOperates on a pre-defined calendar, allowing for easy scheduling of short-term and long-term courses and ensuring that training sessions are well-organized and predictable.</li><li style=\"text-align: left;\">\r\nEnables effective planning and utilization of available resources, such as trainers, venues, and equipment, to maximize the impact of training programs.</li><li style=\"text-align: left;\">\r\nSupports both scheduled and customized training sessions, catering to diverse training needs within the organization.</li><li style=\"text-align: left;\">\r\nConsolidates information on all training programs, participants, and resources into a single platform, enhancing visibility and control for administrators.</li><li style=\"text-align: left;\">\r\nProvides tools for tracking participant attendance, performance, and progress, ensuring transparency and accountability in training outcomes.</li><li style=\"text-align: left;\">\r\nDesigned with an intuitive interface for both administrators and participants, facilitating easy navigation and efficient management of training activities.</li><li style=\"text-align: left;\">\r\nOffers detailed reports on various aspects of the training programs, supporting data-driven decisions and continuous improvement.</li><li style=\"text-align: left;\">\r\nSuitable for organizations of any size, capable of managing multiple training programs simultaneously and adapting to growing training needs.</li></ul>','','',NULL,'2024-11-20 07:15:14','A'),(26,'Others','Orbit','Y','Supply Chain Management System','','<p style=\"text-align: left;\">Orbit is a robust logistics management solution tailored for Medical Services Corporations, automating essential processes across drug and medical equipment procurement and distribution. Key highlights of Orbit include Comprehensive Procurement Automation, End-to-End Distribution Management, Integrated Maintenance Module, Vendor Payment Processing, Quality Control & Assurance Monitoring and Online Platform for Real-Time Tracking.</p><br>\r\n<p style=\"text-align: left;\">Orbit provides Medical Services Corporations with a holistic solution for effective management of drug and equipment logistics, improving operational efficiency and ensuring timely availability of essential medical resources.</p>','<ul>\r\n    <li style=\"text-align: left;\">Automates each stage of the drug and equipment procurement lifecycle, from planning to payment processing, ensuring streamlined workflows and minimized manual intervention.</li>\r\n    <li style=\"text-align: left;\">\r\n        Manages drug distribution with capabilities for warehousing, quality assurance, and inventory control, including tracking drug flow to hospital stores and from stores to wards/pharmacies.</li>\r\n    <li style=\"text-align: left;\">\r\n        Includes a dedicated maintenance module for medical equipment, covering implementation monitoring, routine maintenance scheduling, and vendor management, ensuring equipment reliability and extended service life.</li>\r\n    <li style=\"text-align: left;\">\r\n        Implements robust quality control processes, tracking drug and equipment standards from procurement through to final delivery in healthcare facilities.</li>\r\n    <li style=\"text-align: left;\">\r\n        Facilitates seamless tender processing and purchase management, helping agencies manage vendor selection, contract finalization, and order processing efficiently.</li>\r\n    <li style=\"text-align: left;\">\r\n        Simplifies vendor payments for both drugs and equipment, with transparent and timely payment mechanisms that foster strong supplier relationships.</li>\r\n    <li style=\"text-align: left;\">\r\n        Provides real-time monitoring of inventory, delivery schedules, and procurement statuses, enhancing transparency and enabling prompt decision-making.</li>\r\n    <li style=\"text-align: left;\">\r\n        Offers a centralized online platform that simplifies access to logistics data, supporting stakeholders with up-to-date information and streamlined processes.</li>\r\n</ul>','','',NULL,'2024-11-20 07:18:42','A'),(27,'Others','Indenture','Y','Order Processing System','','<p style=\"text-align: left;\">Indenture is a comprehensive solution for automating and streamlining the core functions of any Public Construction Corporation. Its highlights include Project Lifecycle Automation, Tender and Order Processing, Progress Monitoring, M Book Management, Bill and Payment Processing, Streamlined Construction Requests and Feasibility Studies and Centralized Platform for Construction Divisions.</p><br>\r\n<p style=\"text-align: left;\">Indenture is designed to optimize and simplify construction activities, ensuring improved productivity, transparency, and control over construction projects. It enables Public Construction Corporations to streamline their operations, ensure effective project monitoring, and manage financials efficiently, optimizing the workflow for all construction activities.</p>','<ul><li style=\"text-align: left;\">Automates the entire construction project lifecycle, from initial project acceptance to final completion, including tasks like feasibility studies, drawing and schedule preparation, and resource allocation.</li><li style=\"text-align: left;\">\r\nStreamlines tender processing and work order generation, facilitating smooth procurement and contract management.</li><li style=\"text-align: left;\">\r\nTracks project milestones and completion stages, providing real-time updates to ensure timely project execution and proactive decision-making.</li><li style=\"text-align: left;\">\r\nSimplifies M Book management for recording work measurements, material usage, and labor, improving accuracy and compliance in construction documentation.</li><li style=\"text-align: left;\">\r\nManages bill processing and payment transactions with vendors, ensuring timely disbursement and efficient financial oversight.</li><li style=\"text-align: left;\">\r\nHandles construction requests, conducts feasibility assessments, and prepares cost estimates, enhancing initial project planning and budgeting.</li><li style=\"text-align: left;\">\r\nHandles construction requests, conducts feasibility assessments, and prepares cost estimates, enhancing initial project planning and budgeting.</li></ul>','','',NULL,'2024-11-20 07:20:15','A'),(28,'Others','eMetier','Y','Online Employment Portal','','<p style=\"text-align: left;\">eMetier is an online employment portal designed to facilitate connections between job seekers and employers. It provides a comprehensive, state-verified database of candidates and employers and offers advanced search functionality to streamline the recruitment process. This formal platform integrates the Employment Exchange with agencies, employers, and candidates, making it easier for employers to find the right talent and for job seekers to discover relevant opportunities.</p><br>\r\n<p style=\"text-align: left;\">eMetier is tailored to foster effective connections between job seekers and employers, streamlining job placement and helping fill roles with well-matched candidates.</p>','<ul><li style=\"text-align: left;\">Connects job seekers with relevant employers by matching CVs to job requirements, ensuring a better fit between candidates and job openings.</li><li style=\"text-align: left;\">\r\nProvides extensive search options, allowing employers to filter candidates by specific skills, experience, location, and other criteria. Similarly, job seekers can search for job postings that best match their qualifications and preferences.</li><li style=\"text-align: left;\">\r\nFeatures a straightforward, intuitive interface for job seekers to submit CVs and apply for jobs, and for employers to review candidate profiles and shortlist potential hires.</li><li style=\"text-align: left;\">\r\nSpeeds up hiring by enabling employers to access a rich pool of qualified candidates, making recruitment more efficient.</li><li style=\"text-align: left;\">\r\nOffers a tracking system where candidates can monitor the status of their applications, improving transparency in the recruitment process.</li></ul>','','',NULL,'2024-11-20 07:16:29','A'),(29,'Others','Panacea','Y','Solution for Clinical Trials Registry','','<p style=\"text-align: left;\">Panacea is a centralized, digital platform developed to implement India\'s national Clinical Trials Registry. Key areas of Panacea include Primary Registry Functionality, Centralized Data Consolidation, Publicly Accessible Portal, Compliance with International Standards and User-Friendly Interface. Panacea enhances transparency in clinical research, providing a unified, accessible resource for health care professionals and decision-makers.  Panacea serves as an essential resource for clinical trial transparency, supporting healthcare decision-making and ensuring a cohesive national registry for India’s clinical research efforts.</p>','<ul><li style=\"text-align: left;\">Functions as the primary registry for clinical trials in India under WHO’s ICTRP, consolidating essential trial data for the country.</li><li style=\"text-align: left;\">\r\nCollects and manages clinical trial data from multiple agencies, ensuring comprehensive and unified access to national clinical research information.</li><li style=\"text-align: left;\">\r\nOffers a free, web-based system that allows healthcare professionals, policymakers, and the public to access clinical trial information easily.</li><li style=\"text-align: left;\">\r\nFacilitates informed healthcare decisions by providing complete and up-to-date clinical trial data to stakeholders.</li><li style=\"text-align: left;\">\r\nEnsures trial registration and reporting meet WHO and ICTRP standards, promoting reliability and data quality in clinical research.</li><li style=\"text-align: left;\">\r\nProvides an intuitive portal, making it straightforward for agencies to register trials and for users to retrieve information.</li></ul>','','',NULL,'2024-11-20 07:23:24','A'),(30,'Others','AdMIRe','Y','Advertisement Monitoring & Information Repository','','<p style=\"text-align: left;\">AdMIRe is a robust solution for streamlining advertisement management within organizations. Key highlights include Centralized Advertisement Request Management, Efficient Release Order Management, Comprehensive Payment Monitoring, Media House Database, Order Acceptance and Billing Management, User-Friendly Platform.</p><br>\r\n<p style=\"text-align: left;\">AdMIRe enables organizations to centralize and automate their advertisement management processes, promoting efficiency, accuracy, and better control over advertising activities. AdMIRe enhances advertisement management by automating core activities, supporting efficient financial oversight, and allowing for better strategic decision-making in advertising operations.</p>','<ul><li style=\"text-align: left;\">Streamlines all advertising-related functions within a single platform, from request submission to payment processing, enhancing overall operational efficiency.</li><li style=\"text-align: left;\">\r\nFacilitates automated submission, verification, and processing of advertisement requests, reducing manual workloads and ensuring prompt approvals.</li><li style=\"text-align: left;\">\r\nSystematically handles the issuance and tracking of release orders, allowing for timely and organized distribution to media outlets.</li><li style=\"text-align: left;\">\r\nManages the entire payment lifecycle, from bill submission by media to final processing, promoting transparency and timely payments.</li><li style=\"text-align: left;\">\r\nMaintains a comprehensive database of media houses, including information on geographical reach, category, and circulation coverage, supporting more targeted advertising placements.</li><li style=\"text-align: left;\">\r\nSimplifies the acceptance of orders and bill submissions by media, streamlining communication and documentation for efficient financial processing.</li><li style=\"text-align: left;\">\r\nOffers a centralized, intuitive platform for managing high volumes of advertisements and ensuring accurate tracking of each stage.</li></ul>','','',NULL,'2024-11-20 07:21:43','A'),(31,'Others','Inmate','Y','Solution for Prisons Department','<ul>    <li style=\"text-align: left;\">Consultancy</li>    <li style=\"text-align: left;\">        Software Design & Development </li>    <li style=\"text-align: left;\">        Project Implementation</li>    <li style=\"text-align: left;\">        Operations and Maintenance Support</li>    <li style=\"text-align: left;\">        Integrations</li></ul>','<p style=\"text-align: left;\">This solution is designed for the Prisons Department to manage comprehensive, end-to-end information about inmates. It maintains details such as personal identification, bail, appeals, parole, remission, and warrants. Historical data is recorded, allowing for the generation of a detailed inmate profile at any point, starting from the initial date of lockup. The system also facilitates easy identification of individuals during subsequent incarcerations.</p>','<ul>\r\n    <li style=\"text-align: left;\">Centralized database for inmate profiles, including personal details, criminal history, sentencing, and medical records.</li>\r\n    <li style=\"text-align: left;\">\r\n        Easy access and update of inmate records, reducing paperwork and manual errors</li>\r\n    <li style=\"text-align: left;\">\r\n        Secure storage ensuring privacy and compliance with legal regulations</li>\r\n    <li style=\"text-align: left;\">\r\n        Automated calculation of release dates and conditional release eligibility based on sentencing rules and behavior.</li>\r\n    <li style=\"text-align: left;\">\r\n        Tracking of inmate health records, including medication schedules, medical history, and wellness checks.</li>\r\n</ul>','','',NULL,'2024-10-10 16:51:07','A'),(32,'Others','Kuber','Y','Asset Management Solution','<ul>    <li style=\"text-align: left;\">Software Design & Development </li>    <li style=\"text-align: left;\">        Project Implementation</li>    <li style=\"text-align: left;\">        Operations and Maintenance Support</li></ul>','<p style=\"text-align: left;\">Kuber is an Asset Management System that offers comprehensive functionality, covering the entire lifecycle of an asset—from acquisition to disposal. It manages various aspects such as custodian details, depreciation, asset transfer between locations, maintenance and repairs, and the eventual retirement or disposal of the asset.</p>','<ul><li style=\"text-align: left;\">Manages the entire lifecycle of assets, from acquisition to disposal.</li><li style=\"text-align: left;\">\r\nMaintains details of asset custodians and tracks asset transfers between locations.</li><li style=\"text-align: left;\">\r\nAutomates the calculation and tracking of asset depreciation over time.</li><li style=\"text-align: left;\">\r\nRecords and monitors maintenance activities, including repair history and schedules.</li><li style=\"text-align: left;\">\r\nProvides a detailed profile of each asset, including historical data and current status.</li><li style=\"text-align: left;\">\r\nManages the processes for asset retirement, disposal, and associated documentation.</li></ul>','','',NULL,'2024-10-10 16:58:48','A'),(33,'Others','SmartWorks','Y','Public Works Management System','<ul><li style=\"text-align: left;\">Software Design & Development </li><li style=\"text-align: left;\">Project Implementation</li><li style=\"text-align: left;\">Operations and Maintenance Support</li></ul>','<p style=\"text-align: left;\">It is an end-to-end solution designed to automate the Works Management of the Public Works Department. The solution encompasses various facilities, including project initiation, sanction management, contract finalization, work progress monitoring, M-book entries, billing, and project closure, ensuring streamlined and efficient management of public works projects.</p>','<ul><li style=\"text-align: left;\">Manages the entire project lifecycle, from initiation to closure, including planning, approval, execution, and completion.</li><li style=\"text-align: left;\">\r\nAutomates the process of obtaining and managing project sanctions and approvals, ensuring compliance and transparency.</li><li style=\"text-align: left;\">\r\nFacilitates contract management, including the finalization of terms and agreements with contractors.</li><li style=\"text-align: left;\">\r\nAutomates the entry, recording, and maintenance of M-books for accurate tracking of work measurements and project activities.</li><li style=\"text-align: left;\">\r\nStreamlines billing procedures and payment processing, ensuring timely and accurate financial management.</li><li style=\"text-align: left;\">\r\nGenerates detailed reports on project status, financials, and performance metrics to support informed decision-making.</li></ul>','','',NULL,'2024-10-10 17:02:49','A'),(34,'Others','SmartWings','Y','Integrated Office Management System','<ul><li style=\"text-align: left;\">Consultancy</li><li style=\"text-align: left;\">Software Design & Development </li><li style=\"text-align: left;\">Project Implementation</li><li style=\"text-align: left;\">Operations and Maintenance Support</li></ul>','\r\n<p style=\"text-align: left;\">It is a solution for office automation that consists of two software applications, STAGE and SmartNet, specifically customized for defense units. STAGE is designed for the processing of files, while SmartNet facilitates intra-office communication between users, enhancing collaboration and operational efficiency within the organization.</p>','<ul><li style=\"text-align: left;\">STAGE streamlines the processing of files, improving workflow efficiency and reducing administrative overhead.</li><li style=\"text-align: left;\">\r\nSmartNet enables seamless intra-office communication, facilitating collaboration among users and ensuring timely information sharing.</li><li style=\"text-align: left;\">\r\nTailored specifically for defense units, ensuring that the system meets the unique operational requirements and security protocols of the organization.</li><li style=\"text-align: left;\">\r\nImplements effective document tracking capabilities to monitor the status of files and ensure accountability.</li><li style=\"text-align: left;\">\r\nIncorporates robust security measures to protect sensitive information and ensure compliance with defense standards.</li></ul>','','',NULL,'2024-10-10 17:16:16','A'),(35,'Others','Dhenu','Y','Integrated Monitoring System for Animal Husbandry & Veterinary Department','<ul><li style=\"text-align: left;\">Consultancy</li><li style=\"text-align: left;\">Software Design & Development </li><li style=\"text-align: left;\">Project Implementation</li><li style=\"text-align: left;\">Operations and Maintenance Support</li></ul>','<p style=\"text-align: left;\">It is an end-to-end solution that facilitates the reinvention and transformation of the Animal Husbandry and Veterinary Department and its directorates. This system enhances project and scheme management through comprehensive monitoring processes, complete tracking of farms and farmers, and proactive disease management. Additionally, Dhenu supports detailed tracking, monitoring, and reporting of artificial insemination activities. The solution also includes features for the identification and tracking of animals through ear-tagging and registration.</p>','<ul><li style=\"text-align: left;\">Facilitates effective management of projects and schemes within the Animal Husbandry and Veterinary Department, enhancing operational efficiency.</li><li style=\"text-align: left;\">\r\nProvides real-time monitoring of departmental activities, ensuring timely interventions and effective resource allocation.</li><li style=\"text-align: left;\">\r\nEnables complete tracking of farms and farmers, promoting better data management and support for agricultural practices.</li><li style=\"text-align: left;\">\r\nSupports proactive measures for disease management, ensuring the health and well-being of livestock through timely interventions and monitoring.</li><li style=\"text-align: left;\">\r\nIncorporates features for identifying and tracking animals through ear-tagging and registration, ensuring accurate record-keeping and management.</li></ul>','','',NULL,'2024-10-10 17:14:48','A'),(36,'Others','Prudence','Y','Court Case Management Solution','<ul>    <li style=\"text-align: left;\">Software Design & Development </li>    <li style=\"text-align: left;\">        Project Implementation</li>    <li style=\"text-align: left;\">        Operations and Maintenance Support</li></ul>','<p style=\"text-align: left;\">Prudence is a Court Case Management System designed to manage and maintain information related to an organization\'s legal cases. The system allows tracking of cases filed by or against the organization, beginning with the receipt of a petition. It also provides the capability to generate a comprehensive case profile summary at any time throughout the legal process.</p>','<ul><li style=\"text-align: left;\">A secure, centralized database for storing and managing case information, documents, and legal records.</li><li style=\"text-align: left;\">\r\nEasy retrieval and update of case files, ensuring accurate and up-to-date information is available to authorized personnel.</li><li style=\"text-align: left;\">\r\nCapture the hearing details and send alert to users regarding the same.</li><li style=\"text-align: left;\">\r\nFacility to capture judgement details and compliance details.</li><li style=\"text-align: left;\">\r\nFacility to capture appeal details and to allocate new case number based on the old case number.</li><li style=\"text-align: left;\">\r\nFacility to capture execution order details and the compliance details</li></ul>','','',NULL,'2024-10-10 16:53:53','A'),(37,'Others','Purple','Y','Purchase & Inventory Management System','<ul><li style=\"text-align: left;\">Software Design & Development </li><li style=\"text-align: left;\">    Project Implementation</li><li style=\"text-align: left;\">    Operations and Maintenance Support</li></ul>','<p style=\"text-align: left;\">It is a solution for managing information related to Purchases and Inventory Control within an organization. The purchasing module manages details such as purchase orders, vendor information, and procurement processes, while the inventory module maintains stock details and oversees the distribution of inventory, ensuring efficient management and control of stock levels.</p>','<ul><li style=\"text-align: left;\">Tracks purchase orders, vendor details, and procurement processes, ensuring streamlined purchasing operations.</li><li style=\"text-align: left;\">\r\nMonitors stock levels in real-time, including item details, quantity, and location within the organization.</li><li style=\"text-align: left;\">\r\nOversees the distribution and movement of inventory to various locations, ensuring accurate tracking and availability.</li><li style=\"text-align: left;\">\r\nSeamlessly integrates with other organizational systems, such as finance and asset management, for enhanced operational efficiency.</li></ul>','','',NULL,'2024-10-10 17:00:54','A'),(38,'Others','SmartService','Y','Call Management System','<ul><li style=\"text-align: left;\">Software Design & Development </li><li style=\"text-align: left;\">Project Implementation</li><li style=\"text-align: left;\">Operations and Maintenance Support</li></ul>','\r\n<p style=\"text-align: left;\">It is a smart tool designed to manage the key activities of a typical service provider, encompassing the entire process from the receipt of a support call to its closure. This system facilitates the generation of completion reports that include the current status of any Annual Maintenance Contracts (AMC), preventive maintenance details, and the status of assigned work.</p>','<ul><li style=\"text-align: left;\">Streamlines the entire process from the receipt of support calls to their resolution and closure, ensuring efficient handling of customer inquiries and issues.</li><li style=\"text-align: left;\">\r\nProvides real-time updates on the status of each support call, including pending actions and resolution timelines, enhancing transparency for both service providers and customers.</li><li style=\"text-align: left;\">\r\nFacilitates the assignment of tasks to service personnel and monitors progress, ensuring accountability and timely resolution of support requests.</li></ul>','','',NULL,'2024-10-10 17:07:14','A'),(39,'Others','VetCares','Y','Culling Management System','<ul><li style=\"text-align: left;\">Consultancy</li><li style=\"text-align: left;\">Software Design & Development </li><li style=\"text-align: left;\">Project Implementation</li><li style=\"text-align: left;\">Operations and Maintenance Support</li></ul>','\r\n<p style=\"text-align: left;\">It is a digital platform designed to manage and streamline Culling Management, ensuring transparency and centralized access to data regarding farmers and animals. The platform facilitates the collection of farmer information and efficiently manages the disbursement of financial compensation to eligible beneficiaries. VetCares enhances the effectiveness and transparency of disease control measures across agricultural communities.</p>','<ul><li style=\"text-align: left;\">Provides a centralized platform for accessing and managing data related to farmers and animals, ensuring efficient information sharing and tracking.</li><li style=\"text-align: left;\">\r\nFacilitates the comprehensive collection and maintenance of farmer details, enabling accurate record-keeping and support for culling processes.</li><li style=\"text-align: left;\">\r\nManages the disbursement of financial compensation to eligible beneficiaries, ensuring timely and transparent payouts.</li><li style=\"text-align: left;\">\r\nSupports proactive disease control efforts, ensuring the health and well-being of livestock and reducing the spread of diseases across agricultural communities.</li><li style=\"text-align: left;\">\r\nEnsures transparency in culling operations and compensation processes, providing clear documentation and audit trails.  </li></ul>','','',NULL,'2024-10-10 17:21:16','A');
/*!40000 ALTER TABLE `kran_solutions` ENABLE KEYS */;
UNLOCK TABLES;

