INSERT INTO `kran_timeline` VALUES (1,'1996','','KRAN Software International was legally established as a company, completing the process of incorporation under applicable laws and regulations.','A','2024-08-14 11:56:56'),(2,'1997','','Automation of Factories and Boilers Department, Govt. of Kerala, the first department in the country for automating Licensing & Compliance activities ','A','2024-08-14 11:57:35'),(3,'1998','','Centralized Electoral Database Management System for Govt. of Kerala. First project in the country to implement a centralized system facilitating online issue of Voter ID Cards. With this automation, within a short period, Kerala State was able to conduct a General Election within 3 Days of notification. ','A','2024-08-14 11:59:48'),(4,'1999','','Common Admission Management System for Professional College Admission in Kerala State. First such project in the country facilitating single window service in a transparent manner.','A','2024-08-14 11:59:58'),(5,'2000','','Electronic Filing System in State Secretariat. First such major attempt to implement Electronic Filing system in the country ','A','2024-08-14 12:00:11'),(6,'2001','','Concept and Proposal for AKSHAYA - Citizen Service Centers for Govt. of Kerala. Implementation consultants for the project which was later replicated across the country with over 50,000 such CSCs in operation ','A','2024-08-14 12:00:21'),(7,'2002','','Modernizing Government Program for Govt. of Kerala, an ADB funded project. IT Consultants for addressing Process improvements in Core Government. Recommended IT implementation in over 40 Departments having major impact in Public Administration. 35 Departments had implemented the recommendations within the target period of 10 years.','A','2024-08-14 12:00:34'),(8,'2003','','','D','2024-08-14 12:01:31'),(9,'2004','','','D','2024-08-14 12:02:51'),(10,'2005','','','D','2024-08-14 12:02:57'),(11,'2006','','KRAN Consulting Pvt Ltd officially established as a private limited company after completing legal incorporation and registration formalities','A','2024-08-14 12:03:14'),(12,'2007','','Consultants and Implementation Agency for Clinical Trial Registry of India. ','A','2024-08-14 12:03:27'),(13,'2008','','The UTN (Universal Trial Number) created and implemented by KRAN is the single Global repository for any Clinical Trial happening in the world. ','A','2024-08-14 12:03:38'),(14,'2009','','Set up the first National Health Accounts for Ministry of Health & Family Welfare, Govt. of India - a WHO funded project ','A','2024-08-14 12:03:48'),(15,'2010','','IT Consultants for the Integrated Financial Management Project for Finance Department, Govt. of Assam. The project was taken up as part of Assam Governance and Public Resource Management Program, funded by ADB. ','A','2024-08-14 12:03:58'),(16,'2011','','Automation of Audit Management in Govt. of Kerala, helping significantly strengthen the Decentralized Administration in Kerala. Ensured 100% audit of all institutions on time by 2014 which resulted in a total fund infusion of nearly Rs. 1,200 Crores into the Panchayats in the State. ','A','2024-08-14 12:04:15'),(17,'2012','','','D','2024-08-14 12:04:23'),(18,'2013','','','D','2024-08-14 12:04:28'),(19,'2014','','Technical Consultants and Support Service Providers to Finance Department, Govt. of Assam. Multiple path breaking initiatives were launched resulting in national recognition. ','A','2024-08-14 12:04:41'),(20,'2015','','KRAN is proudly certified by ISO 9001, which signifies that the company adheres to the stringent standards and guidelines set by the International Organization for Standardization (ISO). ','A','2024-08-14 12:04:50'),(21,'2016','','CPART - Centre for Public Administration Reinvention and Transformation, a new division started aiming for the transformation in Public Administration through research and innovation through emerging technologies ','A','2024-08-14 12:05:04'),(22,'2017','','Solution won the Skoch Order of Merit Award for e-Budget Project and Technology Sabha Award for Enterprise Mobility, for the IFMS Project, Govt of Assam. ','A','2024-08-14 12:05:34'),(23,'2018','','KRAN holds the esteemed certification of ISO 27001, an internationally recognized standard for Information Security Management Systems (ISMS). ','A','2024-08-14 12:05:43'),(24,'2019','','KRAN has achieved the prestigious appraisal as a CMMI Level 3 Company, which signifies the organization\'s dedication to process maturity and excellence in software development and service delivery. ','A','2024-08-14 12:05:56'),(25,'2020','','Technical Consultants and System Integrators for IFMS project for Finance Department, Govt. of Assam - a World Bank funded project.  KRAN has attained the prestigious certification of ISO/IEC 20000-1:2018, the internationally recognized standard for IT Service Management. ','A','2024-08-14 12:06:07'),(26,'2021','','KRAN has achieved the prestigious and exceptional appraisal as a CMMI Level 5 Company, exemplifying the organization\'s unmatched dedication to process optimization, innovation, and delivering consistent, high-quality software solutions and services ','A','2024-08-14 12:06:16'),(27,'2022','','KRAN has been proudly reappraised as a CMMI Level 5 V2.0 Company, a testament to the organization\'s unwavering commitment to excellence, innovation, and best-in-class software solutions and services. ','A','2024-08-14 12:06:27'),(28,'2023','','KRAN achieved a workforce of 200+ employees and expanded its operations by acquiring another office building.  Technical Consultants and System Integrators for Finance Department, Government of Jharkhand for the implementation of key IFMS modules and BI tool. ','A','2024-08-14 12:06:37'),(29,'2024','2024','CPART has initiated a comprehensive domain understanding process, and a well-prepared team has been formed under the guidance of KRAN.','A','2024-10-09 05:59:22');
/*!40000 ALTER TABLE `kran_timeline` ENABLE KEYS */;
UNLOCK TABLES;

