INSERT INTO `news` VALUES (1,'Assam E- Budget','Developed, designed and implemented Assam’s first and India’s second E-budget in two platforms, the web and app. The Budget was presented by Finance Minister Himanta Biswa Sarma at the Legislative Assembly. ','A','2023-07-01 14:49:36','blog-1.jpg','#','N'),(2,'CMMI Dev 1.3 Level 3','Assessed as a CMMI Dev 1.3 Level 3 compliant company in January 2018. CMMI stands for “Capability Maturity Model Integration” and is a model that provides appraisal and training for process improvement in organizations. ','A','2023-07-01 14:49:52','blog-2.jpg','#','N'),(3,'ISO 9001:2015','Certified as a ISO 9001:2015 compliant company in March 2018 by TUV SUD. ISO 9001 is the international standard that specifies requirements for a quality management system (QMS). ','A','2023-07-01 14:50:09','blog-4.jpg','#','N'),(4,'ISO 27001:2013','Certified as a ISO 27001:2013 compliant company in February 2018 by TUV SUD. ISO 27001 (formally known as ISO/IEC 27001:2005) is a specification for an information security management system (ISMS).','A','2023-07-01 14:50:26','blog-3.jpg','#','N'),(5,'Assam budget goes digital','In a first for Assam, the budget will be presented in the electronic format by finance minister Himanta Biswa Sarma on Monday','A','2023-07-01 14:50:41','blog-7.jpg','www.timesofindia.indiatimes.com/city/guwahati/assam-budget-goes-digital-to-be-streamed-on-social-media/articleshow/63262807.cms','N'),(6,'First e-Budget on Google Play','Assam’s Finance Minister Himanta Biswa Sarma would present the state’s first e-Budget in the Legislative Assembly on Monday','A','2023-07-01 14:50:54','blog-9.jpg','www.india.com/news/india/assam-set-to-live-stream-first-e-budget-on-google-play-legislators-to-be-given-tablets-with-details-2938661/','N'),(7,'To Present State\'s First E-Budget','The Assam government will present the first e-Budget in the Assembly and each legislator will be provided with a tablet (computer) with details of the Budget','A','2023-07-01 14:51:08','blog-8.jpg','www.ndtv.com/india-news/assam-finance-minister-himanta-biswa-sarma-to-present-states-first-e-budget-on-monday-1822544','N'),(8,'e-Budget in Assembly ','The government will present the first e-Budget in the Assembly and each legislator will be provided with a tablet (computer) with details of the Budget,','A','2023-07-01 14:51:23','blog-10.jpg','www.youtube.com/watch?v=FoGEBb9sxsk','N'),(9,'Factories and Boilers online System','Factories and Boilers Online System have been one of the \"Top 100 Projects in India\" for the year 2016.','A','2023-07-01 14:51:40','Skoch.jpg','popularvote1.skoch.in/','N'),(10,'Technology Sabha Award  2018','Technology Sabha encompasses Learning (expert speakers, panel discussions, case studies, power discussions and best practices in e-governance), Technology Showcase (Exhibition), pre-fixed peer to peer  Networking & relationship building, all of which are part of this prestigious E-Governance forum.','A','2023-07-01 14:51:53','TSA.jpg','www.technologysabha.com/','N'),(11,'SKOCH AWARD 2018 - The Benchmark Of Best Practices','Finance Department Of Assam Government has been awarded SKOCH Order Of Merit 2018.','A','2023-07-01 14:52:21','0.30273688879305505@-@Skoch.jpg','http://www.skoch.in/','N'),(12,'Microsoft India MD Mr Sashikumar Sreedharan recently visited KRAN Campus','An informative and interactive session with Microsoft India MD Mr Sashikumar Sreedharan on the latest innovations and possibilities in the Industry','A','2023-07-01 14:52:37','photo_2019-08-22_14-30-02.jpg','www.kran.co.in/KranConsulting/gallery','N'),(13,'SAP Officials Visited Kran Campus','SAP officials have visited Kran Campus for exploring the technology partnership and more business opportunities.','A','2024-08-02 13:21:33','projects3.jpg','www.kran.co.in/KranConsulting/gallery','N'),(14,'CMMI Dev 1.3 Level 5','Assessed as a CMMI Dev 1.3 Level 5 compliant company in September 2019. CMMI stands for “Capability Maturity Model Integration” and is a model that provides appraisal and training for process improvement in organizations. ','A','2024-08-02 13:21:05','projects2.jpg','#','N'),(16,'Launch of Auto Renewal of Licenses, Kerala Factories & Boilers by the Hon\'ble Labour Minister of Kerala','<p style=\"text-align: justify;\">A website for all government employees of the state to share stories about the people they have helped during this Covid19 crisis. 776 stories and more than 250 contributions made so far.</p>','A','2023-05-11 15:35:56','0.2953906156695931@-@news4.jpg','www.youtube.com/watch?v=zmZ3uVlSMPA','N'),(18,'Launch of Migrant Outreach Portal - Press Conference at NHM Office on COVID 19 ','<p style=\"text-align: left;\">More than 6 lakh calls registered in just 24 hours. An effective tool for the government to help the people of their own state and to reach out to as many stranded migrants as possible at the earliest.</p>','A','2024-08-02 13:20:29','projects1.jpg','www.youtube.com/watch?v=rHKAp8twFrs','N'),(20,'Outreach initiative to help the lakhs of people from the state stranded because of the nationwide lockdown.','It aims to help the lakhs of people from the state stranded outside because of the nationwide lockdown, has provided it with “valuable information” to plan its response on regulating the huge inflow, mostly from Covid-19-affected states.','A','2020-11-17 00:59:32','migrants.jpg','www.telegraphindia.com/states/north-east/migrants-in-times-of-coronavirus-assam-government-shows-it-cares-for-its-own/cid/1766613','N');
/*!40000 ALTER TABLE `news` ENABLE KEYS */;
UNLOCK TABLES;

